return {hdnpc0301={id="hdnpc0301",dsc="他裹着一件黑斗篷，一直笑眯眯的，似乎很和善。",sex="男",age=25,looks=17,showequip={},withCorpse=0},hdnpc0301a={id="hdnpc0301a",dsc="他此时看起相貌堂堂，一双眼睛射寒星，两弯剑眉如刷漆，气宇轩昂。",sex="男",age=25,looks=17,showequip={},withCorpse=0},hdnpc0302={id="hdnpc0302",dsc="她虽然练的是唐门和落月的武学，却自称是大燕复国的希望。其实是一个十足的小鬼头，被安排到红松阁天天练功做苦力。",sex="女",age=10,looks=21,showequip={},withCorpse=0},hdnpc0302a={id="hdnpc0302a",dsc="她此时正躲在草丛里，见你来了才露出一个脑袋与你说话。",sex="女",age=10,looks=21,showequip={},withCorpse=0},hdnpc0303={id="hdnpc0303",dsc="他裹着斗篷，蒙着面，看不清脸，十分神秘。",sex="野兽",age=0,looks=0,showequip={},withCorpse=0},hdnpc0304={id="hdnpc0304",dsc="他瘦瘦小小的，功力似乎也不强，叫人感觉不到威胁。",sex="男",age=30,looks=17,showequip={},withCorpse=0},hdnpc0304a={id="hdnpc0304a",dsc="他此时变得十分的健壮，面容也苍老了许多，和方才简直判若两人。",sex="男",age=30,looks=17,showequip={},withCorpse=0},hdnpc0305={id="hdnpc0305",dsc="他简单的束着发，穿一身灰色道袍，看起来甚是和蔼。",sex="男",age=60,looks=20,showequip={},withCorpse=0},hdnpc0306={id="hdnpc0306",dsc="一个刚入江湖的初生牛犊，武功看起来十分微弱。",sex="男",age=20,looks=19,showequip={},withCorpse=0},hdnpc0306a={id="hdnpc0306a",dsc="一个刚入江湖的初生牛犊，但此时他的功力变得深不可测起来。",sex="男",age=20,looks=19,showequip={},withCorpse=0},hdnpc0307={id="hdnpc0307",dsc="他裹着黑衣，蒙着面，叫你看不清他的面容。",sex="野兽",age=0,looks=0,showequip={},withCorpse=0},hdnpc0308={id="hdnpc0308",dsc="一个来集市闲逛的侠士。",sex="男",age=30,looks=19,showequip={},withCorpse=0},hdnpc0309={id="hdnpc0309",dsc="一个来集市闲逛的侠士。",sex="男",age=33,looks=20,showequip={},withCorpse=0},hdnpc0310={id="hdnpc0310",dsc="似乎是个武当道长，下山游历正好来此集市逛逛。",sex="男",age=43,looks=25,showequip={},withCorpse=0},hdnpc0311={id="hdnpc0311",dsc="她是红松阁的新人。勤勤恳恳，任劳任怨地完成阁中的工作。",sex="女",age=10,looks=23,showequip={},withCorpse=0},hdnpc0312={id="hdnpc0312",dsc="他手臂绘有淡淡的刺青，一头长发用木簪盘起，虽然身为男子，长相却比寻常女子还要秀气。",sex="男",age=20,looks=24,showequip={},withCorpse=0},hdnpc0313={id="hdnpc0313",dsc="他脸上时常带着轻蔑的笑容，看起来狂傲非常，叫人不喜。",sex="男",age=43,looks=21,showequip={},withCorpse=0},hdnpc0314={id="hdnpc0314",dsc="此人曾是戍卫边疆的武官，身长八尺有余，豹头环眼，壮如蛮牛，皮肤黝黑，下颚上留有钢针般遒劲的浓密胡须，却不知为何住在了这平安小镇内。",sex="男",age=49,looks=18,showequip={},withCorpse=0},hdnpc0315={id="hdnpc0315",dsc="他带着斗笠，遮住了面容，但一身正气，叫人不可忽视。",sex="野兽",age=0,looks=0,showequip={},withCorpse=0},hdnpc0316={id="hdnpc0316",sex="男",age=35,looks=17,showequip={},withCorpse=0},hdnpc0317={id="hdnpc0317",dsc="他是庆福坊的掌柜，经常笑眯眯的坐在柜台后边，虽然平时一毛不拔，但佳节时他也会好说话许多。",sex="男",age=46,looks=19,showequip={},withCorpse=0},hdnpc0318={id="hdnpc0318",dsc="此女衣着华丽，但两只长袖已被她用丝带绑起，双手各持一笔，在书籍上写写画画。",sex="女",age=29,looks=19,showequip={},withCorpse=0},hdnpc0319={id="hdnpc0319",dsc="他背着一把竹伞，看起来只是一名文弱书生。",sex="男",age=38,looks=20,showequip={},withCorpse=0},hdnpc0320={id="hdnpc0320",dsc="他总是一副温文尔雅的样子，一把折扇从不离手。",sex="男",age=40,looks=22,showequip={},withCorpse=0},hdnpc0321={id="hdnpc0321",dsc="是个游历的和尚，正巧碰上集市，便来此逛逛。",sex="男",age=38,looks=17,showequip={},withCorpse=0},hdnpc0322={id="hdnpc0322",dsc="她打扮得很是素朴，但看起来武功不低。",sex="女",age=35,looks=18,showequip={},withCorpse=0},hdnpc0323={id="hdnpc0323",dsc="是近来江南名声大燥的名伶，不知道因何来此处唱戏。",sex="女",age=24,looks=24,showequip={},withCorpse=0},hdnpc0324={id="hdnpc0324",dsc="据说是附近城镇一个武馆的教头，闲来无事来此游逛。",sex="男",age=30,looks=20,showequip={},withCorpse=0},hdnpc0325={id="hdnpc0325",dsc="与其说是来参加集市的，不如说是追着秋水来的。",sex="男",age=28,looks=22,showequip={},withCorpse=0},hdnpc0326={id="hdnpc0326",dsc="不知是哪个门派的弟子，懵懵懂懂的样子似乎是第一次下山。",sex="女",age=23,looks=21,showequip={},withCorpse=0},hdnpc0327={id="hdnpc0327",dsc="手艺精湛的捏面人，无论什么都能捏得惟妙惟肖。",sex="男",age=55,looks=17,showequip={},withCorpse=0},hdnpc0328={id="hdnpc0328",dsc="传闻他有一副祖传的糖葫芦秘方，做的糖葫芦酸甜可口，一品难忘。",sex="男",age=45,looks=16,showequip={},withCorpse=0},hdnpc0329={id="hdnpc0329",dsc="据说是从川蜀而来的侠士。",sex="男",age=35,looks=15,showequip={},withCorpse=0},hdnpc0330={id="hdnpc0330",dsc="一个来集市闲逛的侠士。",sex="男",age=33,looks=19,showequip={},withCorpse=0},hdnpc0331={id="hdnpc0331",dsc="与海侠士似乎有很深的恩怨，一见面便会争吵。",sex="男",age=40,looks=18,showequip={},withCorpse=0},hdnpc0332={id="hdnpc0332",dsc="慕名而来的侠士，似乎与铁侠士有很深的恩怨。",sex="男",age=41,looks=19,showequip={},withCorpse=0},hdnpc0333={id="hdnpc0333",dsc="小娥的师姐，为了照看师妹一起下山。",sex="女",age=25,looks=20,showequip={},withCorpse=0},hdnpc0334={id="hdnpc0334",dsc="擅舞大刀的侠女，性情直爽如火。",sex="女",age=36,looks=18,showequip={},withCorpse=0}}00000